def insert(intervals, newInterval):
    allv = sorted([list(x) for x in intervals] + [list(newInterval)])
    out = []
    for s, e in allv:
        if out and s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return out
